// Package version — `version.ts` is generated by buildit (`__APP_VERSION__`).
// Consumers **outside the core** import it from here (`VERSION`); internal
// modules that need the constant (`app-config.ts`, `tj3-config.ts`) import the
// `version.ts` leaf directly, so the barrel does not create module cycles.
export { APP_VERSION as VERSION, } from "./version.ts";

// Application metadata (name, version) — source of the `version`/`help`
// sections of the envelope and of the CLI header (phase 24).
export * from "./app-config.ts";

